'use strict';

// MODULES //

var tape = require( 'tape' );
var abs = require( '@stdlib/math/base/special/abs' );
var FLOAT64_INV_TWO_PI = require( './../lib' );


// TESTS //

tape( 'main export is a number', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof FLOAT64_INV_TWO_PI, 'number', 'main export is a number' );
	t.end();
});

tape( 'the exported value is a double-precision floating-point number equal to 0.15915494309189535', function test( t ) {
	t.strictEqual( FLOAT64_INV_TWO_PI, 0.15915494309189535, 'returns expected value' );
	t.end();
});

tape( 'the exported value equals 1/(2*PI) within double-precision tolerance', function test( t ) {
	var expected = 1.0 / ( 2.0 * 3.141592653589793 );
	var delta = abs( FLOAT64_INV_TWO_PI - expected );
	var tol = 1.0e-15; // double-precision tolerance
	t.ok( delta <= tol, 'within tolerance. expected: '+expected+'. actual: '+FLOAT64_INV_TWO_PI+'. delta: '+delta+'. tol: '+tol+'.' );
	t.end();
});
